import { AppstoreOutlined, BgColorsOutlined, BlockOutlined, BookOutlined, CloudDownloadOutlined, CodeOutlined, DashboardOutlined, DatabaseOutlined, DeleteOutlined, EditOutlined, ExportOutlined, FileImageOutlined, FolderOpenOutlined, GlobalOutlined, HistoryOutlined, LinkOutlined, MenuFoldOutlined, MenuUnfoldOutlined, MoreOutlined, PlusOutlined, RocketOutlined, SearchOutlined, SettingOutlined, ThunderboltOutlined, UploadOutlined } from '@ant-design/icons';
