const { Header, Sider, Content } = Layout;
const categories: Record<string, string> = { character: '角色', combat: '战斗', economy: '经济', ui: '界面', audio: '音频', map: '地图', environment: '环境' };

function useLoad<T>(url: string, deps: unknown[] = []) {
  const [data, setData] = useState<T>(); const [loading, setLoading] = useState(true); const [nonce, setNonce] = useState(0);
  useEffect(() => { let live = true; setLoading(true); api.get(url).then((r) => live && setData(r.data)).finally(() => live && setLoading(false)); return () => { live = false; }; }, [url, nonce, ...deps]);
  return { data, loading, refresh: () => setNonce((x) => x + 1) };
}

function Login() {
  const { message } = App.useApp(); const [busy, setBusy] = useState(false);
  const submit = async ({ token }: { token?: string }) => { setBusy(true); try { await api.post('/auth/login', { token }); if (token) localStorage.setItem('studio-token', token); else localStorage.removeItem('studio-token'); location.reload(); } catch (e) { message.error(unwrapError(e)); } finally { setBusy(false); } };
  return <div className="login-page"><div className="login-art"><div className="brand-mark large">2D</div><div><span className="signal"><i /> SYSTEM READY</span><h1>把创意变成<br/><em>可交付的游戏素材</em></h1><p>统一生成、管理、追踪与导出每一份 2D 游戏资产。</p></div><div className="login-metrics"><span>ASSET GRAPH</span><span>VERSION SAFE</span><span>PHASER READY</span></div></div><Card className="login-card"><div className="eyebrow">ADMIN CONSOLE</div><h2>进入素材工作室</h2><p>使用管理员令牌开始本次创作会话。</p><Form layout="vertical" onFinish={submit}><Form.Item label="管理员令牌" name="token"><Input.Password size="large" placeholder="未配置时可留空" /></Form.Item><Button size="large" type="primary" htmlType="submit" loading={busy} block>进入 Studio</Button></Form><div className="login-note"><span className="pulse"/> 私有工作空间 · 密钥仅发送至服务端</div></Card></div>;
}

const menuItems: MenuProps['items'] = [
  { key: '/', icon: <DashboardOutlined />, label: '资源中枢' },
  { type: 'group', label: '生产', children: [{ key: '/generate', icon: <ThunderboltOutlined />, label: 'AI 生产台' }, { key: '/assets', icon: <FileImageOutlined />, label: '素材库' }, { key: '/maps', icon: <GlobalOutlined />, label: '地图工作区' }] },
  { type: 'group', label: '组织', children: [{ key: '/games', icon: <AppstoreOutlined />, label: '游戏管理' }, { key: '/levels', icon: <BlockOutlined />, label: '关卡管理' }, { key: '/styles', icon: <BgColorsOutlined />, label: '风格规范' }, { key: '/types', icon: <DatabaseOutlined />, label: '素材类型' }, { key: '/settings', icon: <SettingOutlined />, label: '系统设置' }] },
  { type: 'group', label: '交付', children: [{ key: '/exports', icon: <ExportOutlined />, label: '导出中心' }, { key: '/relations', icon: <LinkOutlined />, label: '引用关系' }] },
];

function Shell() {
  const navigate = useNavigate(); const location = useLocation(); const { collapsed, setCollapsed } = useStudioStore();
  return <Layout className="shell"><Sider width={244} collapsedWidth={76} collapsed={collapsed} className="sider"><div className="brand" onClick={() => navigate('/')}><div className="brand-mark">2D</div>{!collapsed && <div><strong>GAME ASSET</strong><span>STUDIO</span></div>}</div><Menu theme="dark" mode="inline" selectedKeys={[location.pathname]} items={menuItems} onClick={({ key }) => navigate(key)} /><div className="sider-foot"><span className="pulse"/>{!collapsed && <span>Studio online</span>}</div></Sider><Layout><Header className="topbar"><Button type="text" icon={collapsed ? <MenuUnfoldOutlined/> : <MenuFoldOutlined/>} onClick={() => setCollapsed(!collapsed)} /><div className="topbar-right"><Tooltip title="API 文档"><Button type="text" href="/api/docs" target="_blank" icon={<CodeOutlined/>}/></Tooltip><Divider type="vertical"/><div className="workspace"><Avatar size={30}>A</Avatar><span><strong>管理员</strong><small>私有空间</small></span></div></div></Header><Content className="content"><Routes><Route path="/" element={<Dashboard/>}/><Route path="/games" element={<Games/>}/><Route path="/levels" element={<Levels/>}/><Route path="/types" element={<Types/>}/><Route path="/styles" element={<Styles/>}/><Route path="/assets" element={<Assets/>}/><Route path="/generate" element={<Generate/>}/><Route path="/settings" element={<Settings/>}/><Route path="/exports" element={<Exports/>}/><Route path="/relations" element={<Relations/>}/><Route path="/maps" element={<Maps/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes></Content></Layout></Layout>;
}

export default function StudioApp() { const [checked, setChecked] = useState(false); const [authed, setAuthed] = useState(false); useEffect(() => { api.post('/auth/login', { token: localStorage.getItem('studio-token') || undefined }).then(() => setAuthed(true)).catch(() => setAuthed(false)).finally(() => setChecked(true)); }, []); if (!checked) return <div className="boot"><div className="brand-mark large">2D</div><span>LOADING STUDIO</span></div>; return authed ? <Shell/> : <Login/>; }

function Dashboard() {
  const navigate = useNavigate(); const { data, loading } = useLoad<any>('/dashboard'); const counts = data?.counts || {};
  const statLinks: Record<string, string> = { PROJECTS: '/games', LEVELS: '/levels', ASSETS: '/assets', 'AI JOBS': '/generate' };
  return <><PageHeader eyebrow="CONTROL ROOM / OVERVIEW" title="资源中枢" description="从想法到 Phaser 交付，掌握每份素材的生产状态与依赖。" actions={<Space><Button icon={<UploadOutlined/>} onClick={() => navigate('/assets')}>上传素材</Button><Button type="primary" icon={<ThunderboltOutlined/>} onClick={() => navigate('/generate')}>开始 AI 生成</Button></Space>}/><Loading loading={loading}><div className="hero-grid"><Card className="command-card"><div className="command-copy"><span className="signal"><i/> PIPELINE NOMINAL</span><h2>下一份素材，<br/>从清晰的规范开始。</h2><p>风格档案会自动约束镜头、色彩、比例与透明背景，让同一游戏的素材保持一致。</p><Button type="primary" icon={<RocketOutlined/>} onClick={() => navigate('/generate')}>打开生产台</Button></div><div className="orbital"><div className="orbital-core">AI</div><i/><i/><i/><span>SPEC</span><span>IMAGE</span><span>ASSET</span></div></Card><Card className="readiness dashboard-link" onClick={() => navigate('/assets?status=published')}><div className="card-kicker">交付准备度</div><Progress type="dashboard" percent={counts.assets ? Math.round((counts.published / counts.assets) * 100) : 0} strokeColor="#b8ff5a" trailColor="#222b38"/><div className="readiness-copy"><strong>{counts.published || 0} / {counts.assets || 0}</strong><span>份素材已发布</span></div><Button type="link" onClick={(e) => { e.stopPropagation(); navigate('/exports'); }}>检查并导出 →</Button></Card></div><Row gutter={[16,16]} className="stat-row">{[[counts.games,'游戏项目','PROJECTS'],[counts.levels,'关卡','LEVELS'],[counts.assets,'素材总量','ASSETS'],[counts.tasks,'生成任务','AI JOBS']].map(([value,label,code],i) => <Col xs={12} xl={6} key={code}><Card hoverable className="stat-card dashboard-link" onClick={() => navigate(statLinks[String(code)])}><span className={`stat-index s${i}`}>0{i+1}</span><Statistic title={label} value={value || 0}/><small>{code}</small></Card></Col>)}</Row><div className="section-title"><div><span>LATEST ACTIVITY</span><h2>最近更新</h2></div><Button type="link" onClick={() => navigate('/assets')}>查看全部素材</Button></div>{data?.recent?.length ? <Row gutter={[16,16]}>{data.recent.map((a: Asset) => <Col xs={24} md={12} xl={8} key={a.assetId}><AssetMini asset={a} onClick={() => navigate(`/assets?search=${encodeURIComponent(a.assetId)}`)}/></Col>)}</Row> : <EmptyPanel icon={<FolderOpenOutlined/>} title="工作室已就绪" text="先创建一个游戏和风格规范，再生成第一份素材。" action={<Button onClick={() => navigate('/games')}>创建游戏</Button>}/>}</Loading></>;
}

function Settings() {
  const runtime = useLoad<{ aiProvider: string; aiApiBaseUrl: string; aiImageModel: string; hasAiApiKey: boolean }>('/runtime-config');
  return <><PageHeader eyebrow="SYSTEM / SETUP" title="系统设置" description="AI 参数读取自服务器 `/root/platform/.env`。这里展示当前值和正确的填写方式，不暴露密钥本身。" /><Row gutter={[18,18]}><Col xs={24} xl={11}><Card title="AI 接入怎么填"><List size="small" dataSource={['打开服务器 `/root/platform/.env`', '设置 `AI_PROVIDER=openai-compatible` 或 `mock`', '填写 `AI_API_BASE_URL` 和 `AI_API_KEY`', '保存后重启 `platform.service`'] } renderItem={(item)=><List.Item>{item}</List.Item>} /><Divider /><pre className="spec-block"><code>{`AI_PROVIDER=openai-compatible\nAI_API_BASE_URL=https://api.openai.com/v1\nAI_API_KEY=sk-xxxxxxxxxxxxxxxx\nAI_IMAGE_MODEL=gpt-image-1`}</code></pre></Card></Col><Col xs={24} xl={13}><Card title="当前运行时配置"><Loading loading={runtime.loading}><Descriptions column={1} bordered size="small" items={[{ label: 'AI_PROVIDER', children: <Tag color="green">{runtime.data?.aiProvider || 'mock'}</Tag> }, { label: 'AI_API_BASE_URL', children: <code>{runtime.data?.aiApiBaseUrl || 'https://api.openai.com/v1'}</code> }, { label: 'AI_IMAGE_MODEL', children: <code>{runtime.data?.aiImageModel || 'gpt-image-1'}</code> }, { label: 'AI_API_KEY', children: <Tag color={runtime.data?.hasAiApiKey ? 'green' : 'orange'}>{runtime.data?.hasAiApiKey ? '已配置' : '未配置'}</Tag> }]}/><Divider /><div className="naming-helper"><span>使用顺序</span><p>先在“游戏管理”“素材类型”“风格规范”里把上下文建好，再进“AI 生产台”提交创意描述、生成 Design Spec，确认 Prompt 后才能真正调用模型。</p></div><Divider /><p style={{color:'#8da0b6',margin:0}}>如果素材类型出现乱码，说明旧的种子数据被错误字符集导入过；我已经修正导入脚本，后续重跑 `seed.sql` 会按 UTF-8 写入。</p></Loading></Card></Col></Row></>;
}

function RuntimeBanner({ runtime }: { runtime?: { aiProvider?: string; aiApiBaseUrl?: string; aiImageModel?: string; hasAiApiKey?: boolean } }) {
  if (!runtime) return null;
  const isMock = runtime.aiProvider === 'mock';
  return <div className={`runtime-banner ${isMock ? 'warn' : 'ok'}`}>{isMock ? '当前 AI_PROVIDER=mock，只会生成占位预览图。请在服务器 .env 里切换为 openai-compatible，然后重启 platform.service。' : `当前 AI_PROVIDER=${runtime.aiProvider || 'openai-compatible'}，图片会走真实模型接口。`}</div>;
}

function RuntimeLogs({ logs }: { logs?: Array<{ ts?: string; level?: string; message?: string; data?: Record<string, unknown> }> }) {
  if (!logs?.length) return <div className="runtime-empty">还没有运行日志。先点击“确认 Prompt 并生成”，日志会在这里逐步出现。</div>;
  return <Timeline items={logs.map((entry, index) => ({ color: entry.level === 'error' ? 'red' : entry.level === 'warn' ? 'gold' : 'green', children: <div className="runtime-log-entry" key={`${entry.ts || 'log'}-${index}`}><strong>{entry.message}</strong><small>{entry.ts ? new Date(entry.ts).toLocaleString() : '刚刚'}</small>{entry.data && <pre>{JSON.stringify(entry.data, null, 2)}</pre>}</div> }))} />;
}

function AssetMini({ asset, onClick }: { asset: Asset; onClick?: () => void }) { const file = asset.versions?.[0]?.files?.find((f:any) => f.mimeType?.startsWith('image/')); return <Card className="asset-mini" hoverable onClick={onClick}><div className="asset-thumb">{file ? <img src={file.publicPath} alt=""/> : <span>{asset.assetType?.typeId?.slice(0,2).toUpperCase()}</span>}<StatusTag status={asset.status}/></div><div className="asset-info"><span>{asset.assetType?.name || '素材'} · {asset.game?.name}</span><h3>{asset.displayName}</h3><code>{asset.assetId}</code><div><Tag bordered={false}>v{String(asset.versions?.[0]?.versionNumber || 1).padStart(3,'0')}</Tag><span>{(asset._count?.incoming || 0)+(asset._count?.outgoing || 0)} 条引用</span></div></div></Card>; }

function EmptyPanel({ icon, title, text, action }: { icon: React.ReactNode; title: string; text: string; action?: React.ReactNode }) { return <div className="empty-panel"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{action}</div>; }

function Games() {
  const { message, modal } = App.useApp(); const { data = [], loading, refresh } = useLoad<Game[]>('/games'); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Game>(); const [form] = Form.useForm();
  const save = async (values:any) => { try { editing ? await api.put(`/games/${editing.id}`, values) : await api.post('/games', values); message.success('游戏已保存'); setOpen(false); setEditing(undefined); form.resetFields(); refresh(); } catch(e){message.error(unwrapError(e));} };
  const edit = (g:Game) => { setEditing(g); form.setFieldsValue(g); setOpen(true); };
  const del = (g:Game) => modal.confirm({ title: `归档 ${g.name}？`, content:'数据将保留，可在数据库中恢复。', okType:'danger', onOk: async()=>{await api.delete(`/games/${g.id}`);refresh();} });
  return <><PageHeader eyebrow="ORGANIZE / PROJECTS" title="游戏管理" description="游戏是风格、关卡、素材和导出的最高层边界。" actions={<Button type="primary" icon={<PlusOutlined/>} onClick={()=>{setEditing(undefined);form.resetFields();setOpen(true)}}>新建游戏</Button>}/><Loading loading={loading} empty={!data.length}><Row gutter={[16,16]}>{data.map((g,i)=><Col xs={24} md={12} xl={8} key={g.gameId}><Card className="project-card"><div className="project-top"><div className={`project-icon c${i%4}`}>{g.name.slice(0,1)}</div><Dropdown menu={{items:[{key:'edit',label:'编辑',icon:<EditOutlined/>,onClick:()=>edit(g)},{key:'del',label:'归档',danger:true,icon:<DeleteOutlined/>,onClick:()=>del(g)}]}}><Button type="text" icon={<MoreOutlined/>}/></Dropdown></div><StatusTag status={g.status}/><h3>{g.name}</h3><code>{g.gameId}</code><p>{g.description || '尚未填写游戏世界与玩法描述。'}</p><div className="project-meta"><span><b>{g._count?.levels||0}</b> 关卡</span><span><b>{g._count?.assets||0}</b> 素材</span></div></Card></Col>)}</Row></Loading><CrudModal title={editing?'编辑游戏':'新建游戏'} open={open} onCancel={()=>setOpen(false)} onOk={()=>form.submit()}><Form form={form} layout="vertical" onFinish={save} initialValues={{status:'draft'}}><Form.Item label="稳定游戏 ID" name="gameId" rules={[{required:true},{pattern:/^[a-z0-9_]+$/,message:'仅允许小写英文、数字和下划线'}]}><Input disabled={!!editing} placeholder="game_forest_guard"/></Form.Item><Form.Item label="显示名称" name="name" rules={[{required:true}]}><Input/></Form.Item><Form.Item label="游戏描述" name="description"><Input.TextArea rows={4}/></Form.Item><Form.Item label="状态" name="status"><Select options={[{value:'draft',label:'草稿'},{value:'published',label:'已发布'},{value:'archived',label:'已归档'}]}/></Form.Item></Form></CrudModal></>;
}

function Levels() {
  const {message}=App.useApp(); const games=useLoad<Game[]>('/games'); const levels=useLoad<Level[]>('/levels'); const [open,setOpen]=useState(false); const [form]=Form.useForm();
  const save=async(v:any)=>{try{await api.post('/levels',v);message.success('关卡已创建');setOpen(false);form.resetFields();levels.refresh();}catch(e){message.error(unwrapError(e))}};
  return <><PageHeader eyebrow="ORGANIZE / LEVELS" title="关卡管理" description="把地图、敌人、塔、技能、波次与奖励组织成可导出的关卡单元。" actions={<Button type="primary" icon={<PlusOutlined/>} onClick={()=>setOpen(true)}>新建关卡</Button>}/><Loading loading={levels.loading} empty={!levels.data?.length}><Table rowKey="id" dataSource={levels.data} pagination={{pageSize:10}} columns={[{title:'关卡',render:(_,r)=><div className="table-title"><span className="number-chip">{String(r.sortOrder+1).padStart(2,'0')}</span><span><strong>{r.name}</strong><code>{r.levelId}</code></span></div>},{title:'所属游戏',render:(_,r)=><Tag>{r.game.name}</Tag>},{title:'素材引用',render:(_,r)=><span>{r._count?.assets||0} 项</span>},{title:'状态',render:(_,r)=><StatusTag status={r.status}/>},{title:'操作',width:100,render:()=><Button type="text" icon={<MoreOutlined/>}/>}]} /></Loading><CrudModal title="新建关卡" open={open} onCancel={()=>setOpen(false)} onOk={()=>form.submit()}><Form form={form} layout="vertical" onFinish={save} initialValues={{sortOrder:0}}><Form.Item label="所属游戏" name="gameId" rules={[{required:true}]}><Select options={games.data?.map(g=>({value:g.gameId,label:g.name}))}/></Form.Item><Form.Item label="稳定关卡 ID" name="levelId" rules={[{required:true},{pattern:/^[a-z0-9_]+$/}]}><Input placeholder="level_forest_001"/></Form.Item><Form.Item label="关卡名称" name="name" rules={[{required:true}]}><Input/></Form.Item><Form.Item label="排序" name="sortOrder"><InputNumber min={0}/></Form.Item><Form.Item label="描述" name="description"><Input.TextArea rows={3}/></Form.Item></Form></CrudModal></>;
}

function Types() { const {message}=App.useApp(); const types=useLoad<AssetType[]>('/asset-types'); const [open,setOpen]=useState(false); const [form]=Form.useForm(); const save=async(v:any)=>{try{await api.post('/asset-types',v);message.success('素材类型已创建');setOpen(false);form.resetFields();types.refresh();}catch(e){message.error(unwrapError(e))}}; const groups=useMemo(()=>Object.entries((types.data||[]).reduce<Record<string,AssetType[]>>((acc,item)=>{(acc[item.category||'other']??=[]).push(item);return acc},{})),[types.data]); return <><PageHeader eyebrow="SYSTEM / TAXONOMY" title="素材类型" description="类型由数据库维护，前端不会写死，可持续扩展新的生产管线。" actions={<Button type="primary" icon={<PlusOutlined/>} onClick={()=>setOpen(true)}>新增类型</Button>}/><Loading loading={types.loading}>{groups.map(([category,items])=><div className="type-group" key={category}><div className="section-title compact"><div><span>{category.toUpperCase()}</span><h2>{categories[category]||'其他'}</h2></div><Badge count={items.length}/></div><div className="type-cloud">{items.map(t=><Card key={t.typeId} className="type-card"><span className="type-glyph">{t.typeId.slice(0,2).toUpperCase()}</span><div><strong>{t.name}</strong><code>{t.typeId}</code></div><Badge status={t.isEnabled?'success':'default'}/></Card>)}</div></div>)}</Loading><CrudModal title="新增素材类型" open={open} onCancel={()=>setOpen(false)} onOk={()=>form.submit()}><Form form={form} layout="vertical" onFinish={save} initialValues={{isEnabled:true}}><Form.Item label="类型 ID" name="typeId" rules={[{required:true},{pattern:/^[a-z0-9_]+$/}]}><Input/></Form.Item><Form.Item label="显示名称" name="name" rules={[{required:true}]}><Input/></Form.Item><Form.Item label="分类" name="category"><Select options={Object.entries(categories).map(([value,label])=>({value,label}))}/></Form.Item><Form.Item label="启用" name="isEnabled" valuePropName="checked"><Switch/></Form.Item></Form></CrudModal></> }

function Styles() { const {message}=App.useApp(); const styles=useLoad<StyleProfile[]>('/styles'); const games=useLoad<Game[]>('/games'); const [open,setOpen]=useState(false); const [form]=Form.useForm(); const save=async(v:any)=>{try{await api.post('/styles',{...v,colorPalette:(v.colorPalette||'').split(',').map((x:string)=>x.trim()).filter(Boolean)});message.success('风格档案已保存');setOpen(false);form.resetFields();styles.refresh();}catch(e){message.error(unwrapError(e))}}; return <><PageHeader eyebrow="CONSISTENCY / ART DIRECTION" title="风格规范" description="把镜头、色板、光线与比例固化为可版本化的生成约束。" actions={<Button type="primary" icon={<PlusOutlined/>} onClick={()=>setOpen(true)}>创建风格档案</Button>}/><Loading loading={styles.loading} empty={!styles.data?.length}><Row gutter={[18,18]}>{styles.data?.map(s=><Col xs={24} lg={12} key={s.styleId}><Card className="style-card"><div className="palette">{(s.colorPalette?.length?s.colorPalette:['#B8FF5A','#75E6FF','#1C2635','#FF766F']).map(c=><i key={c} style={{background:c}}/>)}</div><div className="style-heading"><div><span>{s.game.name} · STYLE v{s.version}</span><h3>{s.styleName}</h3><code>{s.styleId}</code></div><Button type="text" icon={<MoreOutlined/>}/></div><Descriptions size="small" column={2} items={[{key:'1',label:'美术风格',children:s.artStyle||'—'},{key:'2',label:'镜头视角',children:s.cameraAngle||'—'},{key:'3',label:'画布',children:s.frameCanvasSize||'—'},{key:'4',label:'朝向',children:`${s.directionCount||1} 个`}]} /><div className="prompt-preview"><span>PROMPT PREFIX</span>{s.promptPrefix||'尚未配置提示词前缀'}</div></Card></Col>)}</Row></Loading><CrudModal title="创建风格档案" open={open} onCancel={()=>setOpen(false)} onOk={()=>form.submit()} width={680}><Form form={form} layout="vertical" onFinish={save} initialValues={{directionCount:1,frameCanvasSize:'1024x1024'}}><Row gutter={14}><Col span={12}><Form.Item label="所属游戏" name="gameId" rules={[{required:true}]}><Select options={games.data?.map(g=>({value:g.gameId,label:g.name}))}/></Form.Item></Col><Col span={12}><Form.Item label="风格 ID" name="styleId" rules={[{required:true},{pattern:/^[a-z0-9_]+$/}]}><Input/></Form.Item></Col><Col span={12}><Form.Item label="风格名称" name="styleName" rules={[{required:true}]}><Input/></Form.Item></Col><Col span={12}><Form.Item label="美术风格" name="artStyle"><Input placeholder="手绘卡通、硬边阴影"/></Form.Item></Col><Col span={12}><Form.Item label="镜头视角" name="cameraAngle"><Input placeholder="3/4 俯视 45°"/></Form.Item></Col><Col span={12}><Form.Item label="画布尺寸" name="frameCanvasSize"><Input/></Form.Item></Col><Col span={12}><Form.Item label="朝向数量" name="directionCount"><InputNumber min={1} max={16}/></Form.Item></Col><Col span={12}><Form.Item label="色板（逗号分隔）" name="colorPalette"><Input placeholder="#31402a, #c7dc7c"/></Form.Item></Col></Row><Form.Item label="Prompt 前缀" name="promptPrefix"><Input.TextArea rows={3}/></Form.Item><Form.Item label="负面 Prompt" name="negativePrompt"><Input.TextArea rows={2}/></Form.Item></Form></CrudModal></> }

function CrudModal({title,open,onCancel,onOk,children,width}:any){return <Modal title={title} open={open} onCancel={onCancel} onOk={onOk} width={width} okText="保存" cancelText="取消" destroyOnHidden>{children}</Modal>}

function Assets() {
  const {message}=App.useApp(); const location=useLocation(); const games=useLoad<Game[]>('/games'); const types=useLoad<AssetType[]>('/asset-types'); const initialFilters=useMemo(()=>{const p=new URLSearchParams(location.search);return {gameId:p.get('gameId')||'',typeId:p.get('typeId')||'',status:p.get('status')||'',search:p.get('search')||''}},[location.search]); const [filters,setFilters]=useState(initialFilters); useEffect(()=>setFilters(initialFilters),[initialFilters]); const query=new URLSearchParams(Object.entries(filters).filter(([,v])=>v)).toString(); const assets=useLoad<Asset[]>(`/assets?${query}`,[query]); const {assetView,setAssetView}=useStudioStore(); const [open,setOpen]=useState(false); const [selected,setSelected]=useState<string>(); const [form]=Form.useForm(); const [drawer,setDrawer]=useState<any>();
  const save=async(v:any)=>{try{await api.post('/assets',{...v,tags:v.tags?.split(',').map((x:string)=>x.trim()).filter(Boolean)});message.success('素材已登记并创建 v001');setOpen(false);form.resetFields();assets.refresh();}catch(e){message.error(unwrapError(e))}};
  const detail=async(id:string)=>{setSelected(id);setDrawer((await api.get(`/assets/${id}`)).data)};
  const columns:any[]=[{title:'素材',render:(_:any,r:Asset)=><div className="table-title"><span className="type-glyph small">{r.assetType.typeId.slice(0,2).toUpperCase()}</span><span><strong>{r.displayName}</strong><code>{r.assetId}</code></span></div>},{title:'游戏',render:(_:any,r:Asset)=>r.game.name},{title:'类型',render:(_:any,r:Asset)=><Tag>{r.assetType.name}</Tag>},{title:'版本',render:(_:any,r:Asset)=>`v${String(r.versions?.[0]?.versionNumber||1).padStart(3,'0')}`},{title:'引用',render:(_:any,r:Asset)=>(r._count?.incoming||0)+(r._count?.outgoing||0)},{title:'状态',render:(_:any,r:Asset)=><StatusTag status={r.status}/>},{title:'',render:(_:any,r:Asset)=><Button type="text" icon={<MoreOutlined/>} onClick={()=>detail(r.assetId)}/>}];
  return <><PageHeader eyebrow="LIBRARY / ASSETS" title="素材库" description="按稳定资源 ID 管理每个版本、文件和上下游引用。" actions={<Space><Button icon={<UploadOutlined/>}>上传文件</Button><Button type="primary" icon={<PlusOutlined/>} onClick={()=>setOpen(true)}>登记素材</Button></Space>}/><Card className="filter-bar"><Input value={filters.search} prefix={<SearchOutlined/>} placeholder="搜索资源 ID 或名称" allowClear onChange={e=>setFilters({...filters,search:e.target.value})}/><Select value={filters.gameId||undefined} allowClear placeholder="全部游戏" options={games.data?.map(g=>({value:g.gameId,label:g.name}))} onChange={v=>setFilters({...filters,gameId:v||''})}/><Select value={filters.typeId||undefined} allowClear placeholder="全部类型" options={types.data?.map(t=>({value:t.typeId,label:t.name}))} onChange={v=>setFilters({...filters,typeId:v||''})}/><Select value={filters.status||undefined} allowClear placeholder="全部状态" options={['draft','review','published','deprecated'].map(v=>({value:v,label:v}))} onChange={v=>setFilters({...filters,status:v||''})}/><Radio.Group value={assetView} onChange={e=>setAssetView(e.target.value)} optionType="button" buttonStyle="solid" options={[{label:<AppstoreOutlined/>,value:'grid'},{label:<DatabaseOutlined/>,value:'table'}]}/></Card><Loading loading={assets.loading} empty={!assets.data?.length}>{assetView==='grid'?<Row gutter={[16,16]}>{assets.data?.map(a=><Col xs={24} md={12} xl={8} key={a.assetId}><AssetMini asset={a} onClick={()=>detail(a.assetId)}/></Col>)}</Row>:<Table rowKey="id" dataSource={assets.data} columns={columns}/>}</Loading><CrudModal title="登记新素材" open={open} onCancel={()=>setOpen(false)} onOk={()=>form.submit()}><Form form={form} layout="vertical" onFinish={save} initialValues={{status:'draft'}}><Form.Item label="所属游戏" name="gameId" rules={[{required:true}]}><Select options={games.data?.map(g=>({value:g.gameId,label:g.name}))}/></Form.Item><Form.Item label="素材类型" name="typeId" rules={[{required:true}]}><Select showSearch options={types.data?.map(t=>({value:t.typeId,label:`${t.name} · ${t.typeId}`}))}/></Form.Item><Form.Item label="稳定资源 ID" name="assetId" rules={[{required:true},{pattern:/^[a-z0-9_]+$/,message:'仅允许小写英文、数字和下划线'}]}><Input placeholder="enemy_forest_goblin"/></Form.Item><Form.Item label="显示名称" name="displayName" rules={[{required:true}]}><Input/></Form.Item><Form.Item label="标签（逗号分隔）" name="tags"><Input/></Form.Item><Form.Item label="描述" name="description"><Input.TextArea rows={3}/></Form.Item></Form></CrudModal><AssetDrawer asset={drawer} open={!!selected} onClose={()=>{setSelected(undefined);setDrawer(undefined)}} refresh={async()=>selected&&detail(selected)}/></>;
}

function AssetDrawer({asset,open,onClose,refresh}:any){const {message}=App.useApp(); const publish=async(v:number)=>{try{await api.post(`/assets/${asset.assetId}/versions/${v}/publish`);message.success('版本已发布');refresh();}catch(e){message.error(unwrapError(e))}}; return <Drawer title={asset?.displayName||'素材详情'} width={720} open={open} onClose={onClose}><Loading loading={!asset}>{asset&&<><div className="detail-hero"><div><Tag>{asset.assetType.name}</Tag><StatusTag status={asset.status}/><h2>{asset.displayName}</h2><code>{asset.assetId}</code></div><div className="detail-glyph">{asset.assetType.typeId.slice(0,2).toUpperCase()}</div></div><Tabs items={[{key:'basic',label:'基本信息',children:<Descriptions column={1} bordered items={[{key:'game',label:'游戏',children:asset.game.name},{key:'desc',label:'描述',children:asset.description||'—'},{key:'tags',label:'标签',children:asset.tags?.map((x:string)=><Tag key={x}>{x}</Tag>)||'—'}]}/>},{key:'versions',label:`版本 ${asset.versions.length}`,children:<Timeline items={asset.versions.map((v:any)=>({color:v.status==='published'?'green':'gray',children:<Card size="small"><Flex justify="space-between"><div><strong>v{String(v.versionNumber).padStart(3,'0')}</strong> <StatusTag status={v.status}/><p>{v.files.length} 个文件 · {new Date(v.createdAt).toLocaleString()}</p></div>{v.status!=='published'&&<Button size="small" onClick={()=>publish(v.versionNumber)}>发布</Button>}</Flex>{v.prompt&&<div className="prompt-preview">{v.prompt}</div>}</Card>}))}/>},{key:'relations',label:'引用关系',children:<><h4>引用其他素材</h4><List dataSource={asset.outgoing} locale={{emptyText:'无出向引用'}} renderItem={(r:any)=><List.Item><Tag>{r.relationType}</Tag>{r.target.assetId}</List.Item>}/><h4>被其他素材引用</h4><List dataSource={asset.incoming} locale={{emptyText:'无入向引用'}} renderItem={(r:any)=><List.Item><Tag>{r.relationType}</Tag>{r.source.assetId}</List.Item>}/></>},{key:'history',label:'生成历史',children:<List dataSource={asset.generationTasks} locale={{emptyText:'没有 AI 生成历史'}} renderItem={(t:any)=><List.Item><StatusTag status={t.status}/><code>{t.taskId}</code></List.Item>}/>}]} /></>}</Loading></Drawer>}

const npcAnimationConfig = 'idle: frames 1-4, frameRate 6, repeat loop\nwalk: frames 5-8, frameRate 8, repeat loop\nattack: frames 9-12, frameRate 10, repeat once\ndie: frames 13-16, frameRate 7, repeat once';
const npcManifest = { image: 'npc_sprite_sheet.png', frameWidth: 256, frameHeight: 256, columns: 4, rows: 4, animations: { idle: { start: 0, end: 3, frameRate: 6, repeat: -1 }, walk: { start: 4, end: 7, frameRate: 8, repeat: -1 }, attack: { start: 8, end: 11, frameRate: 10, repeat: 0 }, die: { start: 12, end: 15, frameRate: 7, repeat: 0 } } };
type SpriteCheck = { label: string; ok: boolean; detail: string };
const stableAssetId = (value = 'npc_sprite_sheet') => value.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80) || 'npc_sprite_sheet';
const sanitizeNpcArtStyle = (value = '') => (value || '2D 俯视/斜俯视，深色服装，霓虹高光，清晰轮廓')
  .replace(/暗色底|深色底|黑色底|暗背景|深色背景|黑色背景|背景为暗色|背景为深色|dark background|black background|solid background|gradient background/gi, '深色服装和霓虹高光')
  .replace(/透明背景要求|透明背景|背景/gi, '')
  .replace(/不是\s*$/g, '')
  .replace(/[，,、]\s*[，,、]+/g, '，')
  .trim();
// bodyType tells the AI provider whether to inject a human-proportions anchor or
// leave the design free for non-human anatomy — see ai.provider.ts generatePrompt().
const npcBodyTypeOptions = [
  { value: 'humanoid', label: '人形（人类比例，两臂两腿，正常面部）' },
  { value: 'creature', label: '怪兽 / 生物（允许非人体型：额外肢体、翅膀、尾巴等）' },
];
// Curated style anchors for the NPC prompt's art-direction clause. Selecting one
// fills the "美术风格" field below (still freely editable afterwards).
const npcStylePresets = [
  { value: 'flat_neon', label: '扁平游戏素材风（默认 · 已验证效果好）', text: '2D 俯视/斜俯视，霓虹高亮，清晰轮廓，游戏素材风格统一' },
  { value: 'dark_realistic', label: '暗黑写实厚涂', text: '暗黑写实厚涂风格，浓郁光影，精细材质质感，略偏写实比例' },
  { value: 'anime_cel', label: '日系卡通渲染', text: '日系动漫赛璨风，鲜艳干净配色，清晰粗描边，夸张灵动比例' },
  { value: 'ink_wash', label: '中国风水墨', text: '中国风水墨写意，留白构图，水墨笔触质感，素雅传统配色' },
  { value: 'pixel_art', label: '像素风格（实验）', text: '16 位像素风格，像素边缘清晰锐利，复古限定色板' },
  { value: 'custom', label: '自定义（手动输入下方文字）', text: '' },
];
const spriteFixHint = (label: string) => {
  if (label.includes('尺寸')) return '重新生成，保持整图 1024x1024，不能输出横版角色展示图。';
  if (label.includes('Alpha') || label.includes('透明') || label.includes('背景')) return '重新生成，必须使用 true transparent PNG，禁止 dark/gradient/solid/checkerboard background。';
  if (label.includes('16 个单元')) return '重新生成，必须 exactly 4 columns x 4 rows，每个 256x256 cell 都放 1 帧。';
  if (label.includes('贴边') || label.includes('裁切')) return '提示词里强调每帧至少 12px transparent padding，武器和耳朵不能碰边。';
  if (label.includes('脚底')) return '提示词里强调 keep feet aligned to the same baseline，角色不要上下跳。';
  if (label.includes('阴影')) return '重新生成，明确 no ground shadow / no soft dark ellipse / no ground。';
  if (label.includes('网格')) return '重新生成，最终 PNG 不能带 grid lines，网格只能网页预览 overlay。';
  if (label.includes('文字') || label.includes('编号')) return '重新生成，禁止 frame numbers、labels、text、watermark。';
  return '调整 Prompt 后重新生成；自动项全部合格后才能登记。';
};
function pngHeader(bytes: Uint8Array) {
  const view = new DataView(bytes.buffer);
  let hasTrns = false;
  for (let offset = 33; offset + 8 < bytes.length;) {
    const length = view.getUint32(offset);
    const type = String.fromCharCode(bytes[offset + 4], bytes[offset + 5], bytes[offset + 6], bytes[offset + 7]);
    if (type === 'tRNS') hasTrns = true;
    if (type === 'IDAT') break;
    offset += length + 12;
  }
  return { width: view.getUint32(16), height: view.getUint32(20), colorType: bytes[25], hasAlpha: bytes[25] === 4 || bytes[25] === 6 || hasTrns };
}
async function inspectSpriteSheet(url: string): Promise<SpriteCheck[]> {
  const buffer = await (await fetch(url)).arrayBuffer();
  const header = pngHeader(new Uint8Array(buffer));
  const img = new Image();
  img.src = URL.createObjectURL(new Blob([buffer], { type: 'image/png' }));
  await img.decode();
  const canvas = document.createElement('canvas'); canvas.width = img.naturalWidth; canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d', { willReadFrequently: true }); if (!ctx) throw new Error('无法读取图片像素');
  ctx.drawImage(img, 0, 0); URL.revokeObjectURL(img.src);
  const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
  const alphaAt = (x: number, y: number) => data[(y * canvas.width + x) * 4 + 3];
  const rgbaAt = (x: number, y: number) => { const i = (y * canvas.width + x) * 4; return { r: data[i], g: data[i + 1], b: data[i + 2], a: data[i + 3] }; };
  let transparent = 0, edge = 0, edgeOpaque = 0, edgeGray = 0;
  for (let y = 0; y < canvas.height; y += 4) for (let x = 0; x < canvas.width; x += 4) if (alphaAt(x, y) === 0) transparent++;
  for (let x = 0; x < canvas.width; x += 2) for (const y of [0, 1, canvas.height - 2, canvas.height - 1]) { const i = (y * canvas.width + x) * 4; edge++; if (data[i + 3] > 8) edgeOpaque++; if (Math.abs(data[i] - data[i + 1]) < 8 && Math.abs(data[i + 1] - data[i + 2]) < 8) edgeGray++; }
  for (let y = 0; y < canvas.height; y += 2) for (const x of [0, 1, canvas.width - 2, canvas.width - 1]) { const i = (y * canvas.width + x) * 4; edge++; if (data[i + 3] > 8) edgeOpaque++; if (Math.abs(data[i] - data[i + 1]) < 8 && Math.abs(data[i + 1] - data[i + 2]) < 8) edgeGray++; }
  const lineRatio = (axis: 'x' | 'y', pos: number) => { let hit = 0, total = 0; for (let i = 0; i < Math.min(canvas.width, canvas.height); i += 2) { total++; if (axis === 'x' ? alphaAt(pos, i) > 20 : alphaAt(i, pos) > 20) hit++; } return hit / total; };
  const blueLineRatio = (axis: 'x' | 'y', pos: number) => { let hit = 0, total = 0; for (let i = 0; i < Math.min(canvas.width, canvas.height); i += 2) { const c = axis === 'x' ? rgbaAt(pos, i) : rgbaAt(i, pos); total++; if (c.a > 20 && c.b > 120 && c.g > 80 && c.r < 90) hit++; } return hit / total; };
  const gridRatio = Math.max(...[256, 512, 768].flatMap((p) => [lineRatio('x', p), lineRatio('y', p)]));
  const blueGridRatio = Math.max(...[256, 512, 768].flatMap((p) => [blueLineRatio('x', p), blueLineRatio('y', p)]));
  let textCells = 0;
  for (let cell = 0; cell < 16; cell++) { const ox = (cell % 4) * 256, oy = Math.floor(cell / 4) * 256; let hits = 0; for (let y = oy + 8; y < oy + 42; y += 2) for (let x = ox + 8; x < ox + 62; x += 2) if (alphaAt(x, y) > 30) hits++; if (hits / (27 * 17) > 0.03) textCells++; }
  const edgeOpaqueRatio = edgeOpaque / edge;
  const cells = Array.from({ length: 16 }, (_, cell) => {
    const ox = (cell % 4) * 256, oy = Math.floor(cell / 4) * 256;
    let pixels = 0, minX = 256, minY = 256, maxX = -1, maxY = -1, borderHits = 0, lowerDarkSoft = 0;
    for (let y = 0; y < 256; y += 2) for (let x = 0; x < 256; x += 2) {
      const px = ox + x, py = oy + y;
      const c = rgbaAt(px, py);
      if (c.a > 20) {
        pixels++; minX = Math.min(minX, x); minY = Math.min(minY, y); maxX = Math.max(maxX, x); maxY = Math.max(maxY, y);
        if (x < 4 || x > 251 || y < 4 || y > 251) borderHits++;
        const luminance = (c.r + c.g + c.b) / 3;
        if (y > 176 && c.a < 230 && luminance < 70) lowerDarkSoft++;
      }
    }
    return { pixels, minX, minY, maxX, maxY, borderHits, lowerDarkSoft };
  });
  const activeCells = cells.filter((cell) => cell.pixels > 1200 && cell.pixels < 52000).length;
  const clippingCells = cells.filter((cell) => cell.borderHits > 8).length;
  const baselines = cells.filter((cell) => cell.pixels > 1200 && cell.maxY >= 0).map((cell) => cell.maxY);
  const baselineRange = baselines.length ? Math.max(...baselines) - Math.min(...baselines) : 999;
  const shadowCells = cells.filter((cell) => cell.lowerDarkSoft > 120).length;
  return [
    { label: '图片尺寸 1024x1024', ok: header.width === 1024 && header.height === 1024, detail: `${header.width}x${header.height}` },
    { label: 'PNG 带 Alpha 透明能力', ok: header.hasAlpha, detail: `colorType=${header.colorType}` },
    { label: '存在透明 Alpha 像素', ok: transparent > 500, detail: `${transparent} 个采样点 alpha=0` },
    { label: '背景不是不透明底色', ok: edgeOpaqueRatio < 0.02, detail: `边缘不透明采样 ${(edgeOpaqueRatio * 100).toFixed(1)}%` },
    { label: '16 个单元都有独立帧内容', ok: activeCells === 16, detail: `${activeCells}/16 个单元通过内容面积检查` },
    { label: '角色没有贴边或裁切', ok: clippingCells === 0, detail: `${clippingCells} 个单元有边界像素风险` },
    { label: '脚底基准线一致', ok: baselineRange <= 18, detail: `最大基准线偏差 ${baselineRange}px` },
    { label: '未检测到地面阴影/软暗影', ok: shadowCells < 2, detail: `${shadowCells} 个单元有底部半透明暗像素` },
    { label: '未检测到内嵌网格线', ok: gridRatio < 0.08 && blueGridRatio < 0.04, detail: `分割线采样 ${(gridRatio * 100).toFixed(1)}%，蓝色线采样 ${(blueGridRatio * 100).toFixed(1)}%` },
    { label: '未检测到棋盘格背景', ok: !(edgeOpaqueRatio > 0.2 && edgeGray / edge > 0.55), detail: `灰阶边缘采样 ${((edgeGray / edge) * 100).toFixed(1)}%` },
    { label: '未检测到角落文字/编号', ok: textCells < 3, detail: `${textCells} 个帧角落有高密度像素` },
    { label: '人工复核：不是转身展示图', ok: true, detail: '确认 16 帧全部同一朝向，不含正面/背面/侧面展示' },
    { label: '人工复核：动作按行排列', ok: true, detail: '第1行 Idle，第2行 Walk，第3行 Attack，第4行 Die' },
    { label: '人工复核：角色身份正确', ok: true, detail: '年轻精灵王子；脸部正常好看；不是老人/巫师；尖长耳和弓箭每帧可见' },
  ];
}
function SpriteSheetPreview({ result, onChecks }: { result: any; onChecks?: (resultId: string, checks: SpriteCheck[]) => void }) {
  const url = result.file?.publicPath; const [checks, setChecks] = useState<SpriteCheck[]>([]); const [mode, setMode] = useState<keyof typeof npcManifest.animations>('idle'); const [tick, setTick] = useState(0);
  useEffect(() => { if (!url) return; inspectSpriteSheet(url).then((items) => { setChecks(items); onChecks?.(result.resultId, items); }).catch((e) => { const items = [{ label: '图片读取检查', ok: false, detail: String(e?.message || e) }]; setChecks(items); onChecks?.(result.resultId, items); }); }, [url, result.resultId, onChecks]);
  useEffect(() => { const anim = npcManifest.animations[mode]; const id = setInterval(() => setTick((v) => (v + 1) % (anim.end - anim.start + 1)), 1000 / anim.frameRate); return () => clearInterval(id); }, [mode]);
  const frameIndex = npcManifest.animations[mode].start + tick; const bg = (index: number) => ({ backgroundImage: `url(${url})`, backgroundSize: '400% 400%', backgroundPosition: `${(index % 4) / 3 * 100}% ${Math.floor(index / 4) / 3 * 100}%` });
  return <div className="sprite-inspector"><div className="sprite-sheet-wrap"><img src={url} alt="NPC sprite sheet"/></div><div className="sprite-preview-row"><div className="anim-player" style={bg(frameIndex)} /><Radio.Group value={mode} onChange={e => { setMode(e.target.value); setTick(0); }} optionType="button" buttonStyle="solid" options={Object.keys(npcManifest.animations).map(k=>({value:k,label:k}))}/></div><div className="frame-strip">{Array.from({length:16},(_,i)=><span key={i} className="frame-thumb" style={bg(i)}><b>{i+1}</b></span>)}</div><div className="review-note">红色项需要按建议重新生成；蓝色“待复核”就在这里人工看图确认。</div><div className="check-list">{checks.map(c=>{const manual=c.label.startsWith('人工复核');return <div key={c.label} className={manual?'manual':c.ok?'ok':'bad'}><Tag color={manual?'blue':c.ok?'green':'red'}>{manual?'待复核':c.ok?'合格':'不合格'}</Tag><span>{c.label}</span><small>{c.detail}</small>{!manual&&!c.ok&&<em>{spriteFixHint(c.label)}</em>}</div>})}</div></div>;
}

function Generate() {
  const {message}=App.useApp(); const games=useLoad<Game[]>('/games'); const levels=useLoad<Level[]>('/levels'); const types=useLoad<AssetType[]>('/asset-types'); const styles=useLoad<StyleProfile[]>('/styles'); const tasks=useLoad<any[]>('/generation/tasks'); const runtime=useLoad<any>('/runtime-config'); const [form]=Form.useForm(); const [registerForm]=Form.useForm(); const [draft,setDraft]=useState<any>(); const [busy,setBusy]=useState(false); const [registering,setRegistering]=useState<any>(); const [spriteChecks,setSpriteChecks]=useState<Record<string,SpriteCheck[]>>({}); const gameId=Form.useWatch('gameId',form); const typeId=Form.useWatch('typeId',form); const isNpc=typeId==='npc';
  useEffect(()=>{if(draft?.status==='queued'||draft?.status==='processing'){const id=setInterval(async()=>{const r=await api.get(`/generation/tasks/${draft.taskId}`);setDraft(r.data);if(['succeeded','failed','cancelled'].includes(r.data.status)){clearInterval(id);tasks.refresh()}},1500);return()=>clearInterval(id)}},[draft?.status,draft?.taskId]);
  useEffect(()=>{if(isNpc)form.setFieldsValue({targetSize:'1024x1024',sheetSize:'1024x1024',frameSize:'256x256',quantity:1,transparent:true,removeShadow:true,facing:'right',bodyType:form.getFieldValue('bodyType')||'humanoid',stylePreset:form.getFieldValue('stylePreset')||'flat_neon',artStyle:form.getFieldValue('artStyle')||npcStylePresets[0].text,animationFrameConfig:npcAnimationConfig});},[isNpc,form]);
  const applyStylePreset=(value:string)=>{const preset=npcStylePresets.find(p=>p.value===value);form.setFieldsValue({stylePreset:value,...(preset&&preset.value!=='custom'?{artStyle:preset.text}:{})});};
  const create=async(v:any)=>{
    setBusy(true);
    try{
      const payload=v.typeId==='npc'?{...v,name:v.name,description:v.description,characterName:v.name,characterDescription:v.description,artStyle:sanitizeNpcArtStyle(v.artStyle),targetSize:'1024x1024',sheetSize:'1024x1024',frameSize:'256x256',quantity:1,transparent:true,removeShadow:true,animation:v.animationFrameConfig}:v;
      const r=await api.post('/generation/draft',payload);
      setDraft(r.data);
      message.success('Design Spec 与 Prompt 已生成，请确认');
    }catch(e){message.error(unwrapError(e))}finally{setBusy(false)}
  };
  const confirm=async()=>{setBusy(true);try{const r=await api.post(`/generation/tasks/${draft.taskId}/confirm`,{prompt:draft.prompt,negativePrompt:draft.negativePrompt});setDraft({...draft,...r.data});message.success('任务已进入生成队列');}catch(e){message.error(unwrapError(e))}finally{setBusy(false)}};
  const retry=async()=>{if(!draft?.taskId)return;setBusy(true);try{const r=await api.post(`/generation/tasks/${draft.taskId}/retry`);setDraft({...draft,...r.data});message.success('已重新进入生成队列');tasks.refresh();}catch(e){message.error(unwrapError(e))}finally{setBusy(false)}};
  const continueGenerate=async()=>{if(!draft?.taskId)return;setBusy(true);try{const r=await api.post(`/generation/tasks/${draft.taskId}/continue`);setDraft((await api.get(`/generation/tasks/${r.data.taskId}`)).data);setSpriteChecks({});message.success('已按当前规格继续生成');tasks.refresh();}catch(e){message.error(unwrapError(e))}finally{setBusy(false)}};
  const regenerate=async()=>{if(!draft?.taskId)return;setBusy(true);try{const r=await api.post(`/generation/tasks/${draft.taskId}/regenerate`,{prompt:draft.prompt,negativePrompt:draft.negativePrompt});setDraft({...draft,...r.data,results:[]});setSpriteChecks({});message.success('已使用当前规格清空并重新生成');tasks.refresh();}catch(e){message.error(unwrapError(e))}finally{setBusy(false)}};
  const refillInput=()=>{if(!draft)return;const input=draft.input||{};const character=draft.designSpec?.character||{};const filledArtStyle=character.artStyle||input.artStyle;const matchedPreset=npcStylePresets.find(p=>p.text&&p.text===filledArtStyle);form.setFieldsValue({gameId:draft.game?.gameId||input.gameId,levelId:draft.level?.levelId||input.levelId,typeId:draft.assetType?.typeId||input.typeId,styleId:draft.styleProfile?.styleId||input.styleId,name:character.name||input.characterName||input.name,description:character.description||input.characterDescription||input.description,weaponType:character.weaponType||input.weaponType,bodyType:character.bodyType||input.bodyType||'humanoid',stylePreset:matchedPreset?matchedPreset.value:'custom',artStyle:filledArtStyle,facing:character.facing||input.facing||'right',targetSize:input.targetSize||draft.modelParams?.size,sheetSize:input.sheetSize||'1024x1024',frameSize:input.frameSize||'256x256',animationFrameConfig:input.animationFrameConfig||npcAnimationConfig,quantity:input.quantity||1,transparent:input.transparent??true,removeShadow:input.removeShadow??true,animation:input.animation});message.success('已回填到左侧生成输入');};
  const openTask=async(taskId:string)=>{setBusy(true);try{const r=await api.get(`/generation/tasks/${taskId}`);setDraft(r.data);message.success('已打开生成任务');}catch(e){message.error(unwrapError(e))}finally{setBusy(false)}};
  const isNpcDraft=draft?.assetType?.typeId==='npc'||draft?.designSpec?.assetKind==='npc_sprite_sheet';
  const rememberSpriteChecks=useCallback((resultId:string,items:SpriteCheck[])=>setSpriteChecks((current)=>({...current,[resultId]:items})),[]);
  const openRegister=(r:any)=>{if(isNpcDraft){const items=spriteChecks[r.resultId]||[];const failed=items.filter((item)=>!item.label.startsWith('人工复核')&&!item.ok);if(!items.length){message.warning('NPC Sprite Sheet 自动检查还没完成，请稍等。');return;}if(failed.length){message.error(`NPC Sprite Sheet 未通过自动检查：${failed[0].label}`);return;}}const name=draft?.designSpec?.subject||draft?.input?.name||form.getFieldValue('name')||'NPC';registerForm.setFieldsValue({assetId:`npc_${stableAssetId(name)}`,displayName:name,levelId:draft?.level?.levelId||form.getFieldValue('levelId')});setRegistering(r);};
  const register=async(v:any)=>{if(!registering)return;setBusy(true);try{await api.post(`/generation/results/${registering.resultId}/register`,v);message.success(isNpcDraft?'已登记 NPC Sprite Sheet，并生成 npc_sprite_sheet.json':'素材版本已登记');setRegistering(undefined);registerForm.resetFields();if(draft?.taskId)setDraft((await api.get(`/generation/tasks/${draft.taskId}`)).data);}catch(e){message.error(unwrapError(e))}finally{setBusy(false)}};
  return <><PageHeader eyebrow="CREATE / AI PIPELINE" title="AI 生产台" description="先结构化创意，再确认最终 Prompt；NPC 会按 1024×1024、4×4、透明 Alpha Sprite Sheet 规格生成。" actions={<Badge status="processing" text={`${tasks.data?.filter(t=>['queued','processing'].includes(t.status)).length||0} 个任务运行中`}/>}/><RuntimeBanner runtime={runtime.data}/><div className="production-grid"><Card className="production-panel input-panel" title={<span><b>01</b> 生产输入</span>}><Form form={form} layout="vertical" onFinish={create} initialValues={{transparent:true,targetSize:'512x512',quantity:1,removeShadow:true,facing:'right',bodyType:'humanoid',stylePreset:'flat_neon'}}><Form.Item label="游戏" name="gameId" rules={[{required:true}]}><Select options={games.data?.map(g=>({value:g.gameId,label:g.name}))}/></Form.Item><Row gutter={10}><Col span={12}><Form.Item label="关卡（可选）" name="levelId"><Select allowClear options={levels.data?.filter(l=>!gameId||l.game.gameId===gameId).map(l=>({value:l.levelId,label:l.name}))}/></Form.Item></Col><Col span={12}><Form.Item label="素材类型" name="typeId" rules={[{required:true}]}><Select showSearch options={types.data?.map(t=>({value:t.typeId,label:t.name}))}/></Form.Item></Col></Row><Form.Item label="风格档案" name="styleId"><Select allowClear options={styles.data?.filter(s=>!gameId||s.game.gameId===gameId).map(s=>({value:s.styleId,label:`${s.styleName} · v${s.version}`}))}/></Form.Item><Form.Item label={isNpc?'角色名称':'素材名称'} name="name" rules={[{required:true}]}><Input placeholder={isNpc?'森林守卫 NPC':'森林哥布林弓箭手'}/></Form.Item><Form.Item label={isNpc?'角色描述':'创意描述'} name="description" rules={[{required:true}]}><Input.TextArea rows={isNpc?4:6} placeholder="描述外形、衣服、颜色、体型、性格与用途…" showCount maxLength={1200}/></Form.Item>{isNpc&&<><Row gutter={10}><Col span={12}><Form.Item label="武器类型" name="weaponType" rules={[{required:true}]}><Input placeholder="短剑 / 弓 / 法杖"/></Form.Item></Col><Col span={12}><Form.Item label="朝向" name="facing"><Select options={[{value:'right',label:'面向右侧'},{value:'left',label:'面向左侧'}]}/></Form.Item></Col></Row><Form.Item label="角色体型" name="bodyType" extra="决定 Prompt 是否强制人形五官比例；怪兽/生物模式允许非人体型。"><Radio.Group optionType="button" buttonStyle="solid" options={npcBodyTypeOptions}/></Form.Item><Form.Item label="美术风格预设" name="stylePreset" extra="选择预设会覆盖下方“美术风格”文字，选完仍可手动修改。"><Select options={npcStylePresets.map(p=>({value:p.value,label:p.label}))} onChange={applyStylePreset}/></Form.Item><Form.Item label="美术风格" name="artStyle" extra="不要填写暗色底/背景；暗色只能用于服装和霓虹高光，最终 PNG 必须透明。"><Input placeholder="Q版塔防，深色服装，霓虹高光，清晰轮廓"/></Form.Item><Row gutter={10}><Col span={12}><Form.Item label="整图尺寸" name="sheetSize"><Input disabled/></Form.Item></Col><Col span={12}><Form.Item label="单帧尺寸" name="frameSize"><Input disabled/></Form.Item></Col></Row><Form.Item label="动画帧配置" name="animationFrameConfig"><Input.TextArea rows={4}/></Form.Item></>} {!isNpc&&<Form.Item label="动画需求" name="animation"><Input placeholder="idle, walk, attack；8 方向"/></Form.Item>}<Row gutter={10}><Col span={10}><Form.Item label="目标尺寸" name="targetSize"><Select disabled={isNpc} options={['512x512','1024x1024','1536x1024'].map(value=>({value,label:value}))}/></Form.Item></Col><Col span={7}><Form.Item label="数量" name="quantity"><InputNumber min={1} max={isNpc?1:4} disabled={isNpc}/></Form.Item></Col><Col span={7}><Form.Item label="透明背景" name="transparent" valuePropName="checked"><Switch disabled={isNpc}/></Form.Item></Col></Row>{isNpc&&<Form.Item label="去除阴影" name="removeShadow" valuePropName="checked"><Switch disabled/></Form.Item>}<Form.Item label="参考图片"><Upload.Dragger multiple beforeUpload={()=>false} showUploadList><UploadOutlined/><p>拖入角色或风格参考图</p><span>第一版先登记本地参考文件</span></Upload.Dragger></Form.Item><Button block type="primary" htmlType="submit" loading={busy} icon={<ThunderboltOutlined/>}>生成 Design Spec</Button></Form></Card><Card className="production-panel result-panel" title={<span><b>02</b> 规格与结果</span>} extra={draft&&<StatusTag status={draft.status}/>}><>{!draft?<EmptyPanel icon={<ThunderboltOutlined/>} title="等待创意输入" text="Design Spec、最终 Prompt 与候选结果会在这里逐步呈现。"/>:<><div className="spec-block"><span>DESIGN SPEC</span><pre>{JSON.stringify(draft.designSpec,null,2)}</pre></div><Form layout="vertical"><Form.Item label="最终 Prompt"><Input.TextArea rows={isNpcDraft?10:6} value={draft.prompt} onChange={e=>setDraft({...draft,prompt:e.target.value})}/></Form.Item><Form.Item label="负面 Prompt"><Input.TextArea rows={3} value={draft.negativePrompt} onChange={e=>setDraft({...draft,negativePrompt:e.target.value})}/></Form.Item></Form><div className="runtime-log"><span>运行日志</span><RuntimeLogs logs={draft.runtimeLogs}/></div><Space.Compact block className="generation-actions"><Button onClick={refillInput}>回填到生成输入</Button>{draft.status==='draft'?<Button type="primary" loading={busy} onClick={confirm}>确认 Prompt 并生成</Button>:<><Button loading={busy} onClick={continueGenerate}>继续生成</Button><Button danger loading={busy} onClick={regenerate}>重新生成并覆盖</Button></>}</Space.Compact>{['queued','processing'].includes(draft.status)&&<div className="generating"><div className="scan-box"><ThunderboltOutlined/></div><h3>正在生成候选素材</h3><p>任务 {draft.taskId}</p><Progress percent={draft.status==='queued'?24:68} status="active" showInfo={false}/></div>}{draft.status==='failed'&&<div className="retry-panel"><Empty description={draft.errorMessage}/><Button type="primary" icon={<ThunderboltOutlined/>} loading={busy} onClick={retry}>重试生成</Button></div>} {runtime.data?.aiProvider==='mock'&&draft.results?.length>0&&<div className="runtime-banner warn">当前是 mock 模式，预览图是占位 PNG，不会通过 NPC Sprite Sheet 尺寸检查。切到 openai-compatible 后再生成真实图。</div>} {draft.results?.length>0&&<div className="result-grid">{draft.results.map((r:any)=><div className="result-image" key={r.resultId}>{isNpcDraft?<SpriteSheetPreview result={r} onChecks={rememberSpriteChecks}/>:<img src={r.file.publicPath} alt="AI 生成候选"/>}<Button type="primary" onClick={()=>openRegister(r)}>登记为素材</Button></div>)}</div>}</>}</></Card><Card className="production-panel context-panel" title={<span><b>03</b> 一致性上下文</span>}><div className="context-list"><div><BgColorsOutlined/><span><b>{isNpc?'NPC 固定规格':'风格自动注入'}</b><small>{isNpc?'1024×1024 / 256×256 / 4×4 / 16 帧':'色板、镜头、光线与轮廓'}</small></span></div><div><HistoryOutlined/><span><b>版本链保留</b><small>主图、父版本与生成参数</small></span></div><div><LinkOutlined/><span><b>关系登记</b><small>技能、子弹、VFX 与音频</small></span></div><div><FileImageOutlined/><span><b>{isNpc?'导出文件':'文件可追溯'}</b><small>{isNpc?'npc_sprite_sheet.png + npc_sprite_sheet.json':'用途、Hash 与物理存储分离'}</small></span></div></div><Divider/><div className="naming-helper"><span>资源命名助手</span><code>{isNpc?`npc_${stableAssetId(form.getFieldValue('name')||'character')}`:`${form.getFieldValue('typeId')||'enemy'}_theme_object_name`}</code><p>仅允许小写英文、数字和下划线；发布后永久稳定。</p></div><Divider/><h4>最近任务</h4><List size="small" dataSource={tasks.data?.slice(0,5)} locale={{emptyText:'暂无生成记录'}} renderItem={(t:any)=><List.Item className="task-list-item" onClick={()=>openTask(t.taskId)}><div><StatusTag status={t.status}/><small>{t.assetType?.name}</small></div><code>{t.taskId.slice(0,13)}…</code></List.Item>}/></Card></div><CrudModal title="登记生成结果" open={!!registering} onCancel={()=>setRegistering(undefined)} onOk={()=>registerForm.submit()}><Form form={registerForm} layout="vertical" onFinish={register}><Form.Item label="稳定资源 ID" name="assetId" rules={[{required:true},{pattern:/^[a-z0-9_]+$/,message:'仅允许小写英文、数字和下划线'}]}><Input/></Form.Item><Form.Item label="显示名称" name="displayName" rules={[{required:true}]}><Input/></Form.Item><Form.Item label="绑定关卡（可选）" name="levelId"><Select allowClear options={levels.data?.filter(l=>!draft?.game?.gameId||l.game.gameId===draft.game.gameId).map(l=>({value:l.levelId,label:l.name}))}/></Form.Item></Form></CrudModal></>;
}

function Exports(){const {message}=App.useApp();const games=useLoad<Game[]>('/games');const levels=useLoad<Level[]>('/levels');const exportsList=useLoad<any[]>('/exports');const [form]=Form.useForm();const scope=Form.useWatch('scopeType',form);const game=Form.useWatch('gameId',form);const create=async(v:any)=>{try{await api.post('/exports',v);message.success('导出完成');exportsList.refresh()}catch(e){message.error(unwrapError(e));exportsList.refresh()}};return <><PageHeader eyebrow="DELIVERY / EXPORTS" title="导出中心" description="先检查版本、文件与关系完整性，再生成可被 Phaser 3 消费的交付包。"/><div className="export-grid"><Card className="export-builder"><div className="card-kicker">NEW PACKAGE</div><h2>创建交付包</h2><Form form={form} layout="vertical" onFinish={create} initialValues={{scopeType:'game'}}><Form.Item label="导出范围" name="scopeType"><Radio.Group buttonStyle="solid" options={[{value:'game',label:'整个游戏'},{value:'level',label:'单个关卡'}]}/></Form.Item><Form.Item label="游戏" name="gameId" rules={[{required:true}]}><Select options={games.data?.map(g=>({value:g.gameId,label:g.name}))}/></Form.Item>{scope==='level'&&<Form.Item label="关卡" name="levelId" rules={[{required:true}]}><Select options={levels.data?.filter(l=>!game||l.game.gameId===game).map(l=>({value:l.levelId,label:l.name}))}/></Form.Item>}<div className="integrity-list"><span><i/>稳定业务 ID</span><span><i/>已发布素材版本</span><span><i/>文件 SHA-256</span><span><i/>关系与关卡引用</span><span><i/>Phaser 加载清单</span></div><Button type="primary" icon={<CloudDownloadOutlined/>} block htmlType="submit">检查并生成 ZIP</Button></Form></Card><Card title="导出记录" className="export-history"><Loading loading={exportsList.loading} empty={!exportsList.data?.length}><List dataSource={exportsList.data} renderItem={(x:any)=><List.Item actions={x.status==='succeeded'?[<Button key="download" href={`/api/exports/${x.exportId}/download`} icon={<CloudDownloadOutlined/>}>下载</Button>]:[]}><List.Item.Meta avatar={<div className="zip-icon">ZIP</div>} title={<Space>{x.game.name}<StatusTag status={x.status}/></Space>} description={<><code>{x.exportId}</code><br/><span>{x.scopeType==='game'?'游戏':'关卡'} · {new Date(x.createdAt).toLocaleString()}</span>{x.errorMessage&&<p className="error-text">{x.errorMessage}</p>}</>}/></List.Item>}/></Loading></Card></div></>}

function Relations(){const assets=useLoad<Asset[]>('/assets');const relations=useLoad<any[]>('/relations');const {message}=App.useApp();const [form]=Form.useForm();const save=async(v:any)=>{try{await api.post('/relations',v);message.success('引用关系已建立');form.resetFields();relations.refresh()}catch(e){message.error(unwrapError(e))}};const relationTypes=['uses_skill','uses_projectile','uses_vfx','uses_audio','drops_item','upgrades_to','summons_enemy','depends_on','variant_of'];return <><PageHeader eyebrow="GRAPH / DEPENDENCIES" title="引用关系" description="用稳定资源 ID 维护依赖，删除前可从任一方向追踪影响范围。"/><Row gutter={[18,18]}><Col xs={24} xl={9}><Card title="建立引用"><Form form={form} layout="vertical" onFinish={save}><Form.Item label="源素材" name="sourceAssetId" rules={[{required:true}]}><Select showSearch optionFilterProp="label" options={assets.data?.map(a=>({value:a.assetId,label:`${a.displayName} · ${a.assetId}`}))}/></Form.Item><Form.Item label="关系" name="relationType" rules={[{required:true}]}><Select options={relationTypes.map(value=>({value,label:value}))}/></Form.Item><Form.Item label="目标素材" name="targetAssetId" rules={[{required:true}]}><Select showSearch optionFilterProp="label" options={assets.data?.map(a=>({value:a.assetId,label:`${a.displayName} · ${a.assetId}`}))}/></Form.Item><Button type="primary" block htmlType="submit" icon={<LinkOutlined/>}>建立关系</Button></Form></Card></Col><Col xs={24} xl={15}><Card title="关系图谱"><Loading loading={relations.loading} empty={!relations.data?.length}><div className="relation-list">{relations.data?.map(r=><div className="relation-row" key={r.id}><div><strong>{r.source.displayName}</strong><code>{r.source.assetId}</code></div><span><i/><Tag>{r.relationType}</Tag><i/></span><div><strong>{r.target.displayName}</strong><code>{r.target.assetId}</code></div></div>)}</div></Loading></Card></Col></Row></>}

function Maps(){const maps=useLoad<any[]>('/maps');return <><PageHeader eyebrow="FUTURE / MAP WORKSPACE" title="地图工作区" description="第一阶段提供地图资源登记与 PixiJS 预览入口，编辑能力通过适配器逐步接入。" actions={<Button disabled icon={<PlusOutlined/>}>新建地图（下一阶段）</Button>}/><div className="map-layout"><Card className="map-canvas" title={<span><Badge status="processing"/> PIXI PREVIEW CANVAS</span>} extra={<Tag>只读预览</Tag>}><PixiMapPreview/><div className="map-legend"><span><i className="path-dot"/> 路线</span><span><i className="tower-dot"/> 建塔点</span><span><i className="enemy-dot"/> 单位预览</span></div></Card><Card className="map-roadmap" title="扩展接口"><div className="adapter-code"><span>interface</span> MapEditorAdapter {'{'}<br/>　importMap(file)<br/>　exportMap(version)<br/>　validateMap(scene)<br/>　toPreviewScene(map)<br/>{'}'}</div><Timeline items={[{color:'green',children:'Map / MapVersion 数据模型'},{color:'green',children:'map 与 tileset 资源类型'},{color:'green',children:'PixiJS 预览画布入口'},{color:'blue',children:'Tiled TMJ 导入与图层编辑'},{children:'路径、波次与 Phaser 实机预览'}]}/><Divider/><small>当前已登记 {maps.data?.length||0} 张地图</small></Card></div></>}
